import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { TimelineResult, InvestigationSummary, KeyFinding, ConfirmedFact, ThreatHypothesis, Recommendation } from '../types';

/**
 * Digital Forensic Reporting & Investigation Summary Service.
 * Stage 4: AI Summary & Digital Forensic Report Export.
 *
 * Design Principles:
 * 1. Evidence-Based Integrity: Derives all conclusions strictly from ingested events. Never invents facts.
 * 2. Transparent Methodology: Clearly identifies summary as generated by an Automated Rule-Based Forensic Analysis Engine.
 * 3. Unmistakable Data Provenance: Displays prominent [DEMO DATA - SIMULATED] banners whenever operating in Demo Mode.
 * 4. Defensible Separation: Distinguishes confirmed physical log facts from heuristic suspicion hypotheses.
 * 5. Actionable Guidance: Provides defensive remediation steps framed as investigative guidance.
 * 6. Client-Side High-Fidelity PDF: Generates defensible, styled digital forensic PDF reports.
 */

export class ForensicReportService {
  static generateInvestigationSummary(
    timelineData: TimelineResult,
    isDemo: boolean = true
  ): InvestigationSummary {
    const summaryMeta = timelineData.summary || {
      total_events: 0,
      threat_level: 'Unknown',
      unique_actors: [],
      targeted_accounts: [],
      created_accounts: [],
      detected_attack_phases: [],
      earliest_event: 'N/A',
      latest_event: 'N/A',
    };
    const timelineItems = timelineData.timeline || [];
    const chains = timelineData.correlation_chains || [];

    const totalEvents = summaryMeta.total_events || timelineItems.length;
    const threatLevel = summaryMeta.threat_level || 'Unknown';
    const actors = summaryMeta.unique_actors || [];
    const targets = summaryMeta.targeted_accounts || [];
    const createdAccounts = summaryMeta.created_accounts || [];
    const phases = summaryMeta.detected_attack_phases || [];
    const earliest = summaryMeta.earliest_event || 'N/A';
    const latest = summaryMeta.latest_event || 'N/A';

    // 1. Executive Summary Synthesis
    const observedIds = Array.from(new Set(timelineItems.map((i) => i.event_id).filter(Boolean))).sort();
    const eventIdsClause = observedIds.length > 0 ? ` (Event IDs observed: ${observedIds.join(', ')})` : '';

    let execSummary = '';
    if (totalEvents === 0) {
      execSummary =
        'No security events were identified in the queried log stream. ' +
        'No active intrusion patterns or policy violations were detected for this analysis window.';
    } else if (threatLevel.includes('Critical')) {
      execSummary =
        `Automated forensic analysis identified a critical multi-stage intrusion sequence comprising ` +
        `${totalEvents} correlated security events between ${earliest} and ${latest}${eventIdsClause}. ` +
        `An external threat actor operating from IP address ${actors.length > 0 ? actors.join(', ') : 'unknown external address'} ` +
        `conducted an initial credential access campaign, achieved successful authentication against ` +
        `the '${targets.join(', ')}' account, elevated administrative privileges, and established persistence ` +
        `by creating unauthorized local user account(s): ${createdAccounts.length > 0 ? createdAccounts.join(', ') : 'N/A'}.`;
    } else if (threatLevel.includes('High')) {
      execSummary =
        `Forensic telemetry analysis detected elevated adversarial activity (${totalEvents} events)${eventIdsClause}. ` +
        `Repeated authentication failures and unauthorized access attempts were identified targeting ` +
        `accounts (${targets.join(', ')}) from source IP (${actors.join(', ')}).`;
    } else {
      execSummary =
        `Analysis of ${totalEvents} events revealed routine baseline operations${eventIdsClause}. ` +
        'No evidence of credential guessing, unauthorized privilege escalation, or persistence creation was observed.';
    }

    // 2. Key Chronological Findings
    const keyFindings: KeyFinding[] = [];
    for (const item of timelineItems) {
      if (item.suspicion_level === 'Critical' || item.suspicion_level === 'High' || item.suspicion_level === 'Suspicious') {
        keyFindings.push({
          step: item.step,
          timestamp: item.timestamp,
          event_id: item.event_id,
          event_name: item.event_name,
          actor: item.actor,
          target: item.target_user,
          phase: item.kill_chain_phase,
          suspicion: item.suspicion_level,
          description: item.correlation_reason,
        });
      }
    }

    // 3. Observed Facts vs. Hypotheses
    const confirmedFactsList: ConfirmedFact[] = [];
    const hypothesesList: ThreatHypothesis[] = [];

    for (const item of timelineItems) {
      confirmedFactsList.push({
        timestamp: item.timestamp,
        event_id: item.event_id,
        fact: item.confirmed_facts,
      });
      if (item.suspicion_level !== 'Informational / Baseline') {
        hypothesesList.push({
          timestamp: item.timestamp,
          event_id: item.event_id,
          suspicion: item.suspicion_level,
          hypothesis: item.correlation_reason,
        });
      }
    }

    // 4. Actionable Defensive Recommendations
    const recommendations: Recommendation[] = [];
    if (totalEvents > 0) {
      if (createdAccounts.length > 0) {
        recommendations.push({
          priority: 'P1 - Critical',
          action: 'Immediate Account Remediation',
          details: `Immediately disable and audit local user account(s): ${createdAccounts.join(', ')}. Check group memberships via 'net localgroup Administrators' and 'net localgroup "Remote Desktop Users"'.`,
        });
      }
      if (actors.length > 0) {
        recommendations.push({
          priority: 'P1 - Critical',
          action: 'Perimeter Network Containment',
          details: `Block inbound traffic from source IP address(es) ${actors.join(', ')} at edge firewalls and host-based Windows Defender Firewall.`,
        });
      }
      if (targets.includes('Administrator') || timelineItems.some((i) => i.event_id === '4672')) {
        recommendations.push({
          priority: 'P2 - High',
          action: 'Credential Invalidation & Kerberos Purge',
          details:
            'Force an immediate password reset for targeted administrative accounts. Purge active Kerberos ticket-granting tickets (TGT) and terminate active RDP/SMB sessions.',
        });
      }
      if (threatLevel.includes('Critical') || threatLevel.includes('High')) {
        recommendations.push({
          priority: 'P2 - High',
          action: 'Endpoint Volatile Memory Preservation',
          details:
            'Preserve volatile RAM image on affected host(s) to inspect for in-memory tools (e.g. Mimikatz, cobalt strike beacons) associated with SeDebugPrivilege assignment.',
        });
        recommendations.push({
          priority: 'P3 - Medium',
          action: 'Account Lockout Policy Hardening',
          details:
            'Implement stricter account lockout thresholds (e.g. 5 failed attempts within a 15-minute observation window) to mitigate password spraying.',
        });
      }
    }

    const now = new Date();
    const pad = (n: number) => n.toString().padStart(2, '0');
    const genAt = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())} UTC`;

    return {
      methodology: 'Automated Rule-Based Forensic Analysis Engine',
      data_provenance: 'DEMO DATASET (SIMULATED & CLOUD FORENSIC TELEMETRY)',
      is_demo: true,
      generated_at: genAt,
      threat_verdict: threatLevel,
      executive_summary: execSummary,
      time_scope: {
        earliest_event: earliest,
        latest_event: latest,
        total_events_analyzed: totalEvents,
      },
      entities: {
        actors,
        targeted_accounts: targets,
        created_accounts: createdAccounts,
        detected_phases: phases,
      },
      key_findings: keyFindings,
      confirmed_facts: confirmedFactsList,
      threat_hypotheses: hypothesesList,
      correlation_chains: chains,
      recommendations,
      forensic_limitations:
        '1. Analysis is scoped exclusively to provided Windows Security Event Logs (IDs 4624, 4625, 4672, 4720).\n' +
        '2. Network layer packet captures and file system MFT forensic timelines were not incorporated in this stage.\n' +
        '3. Recommendations represent investigative defensive guidance and should be validated through full incident response procedures.',
    };
  }

  static generateAndDownloadPdf(
    timelineData: TimelineResult,
    summaryData: InvestigationSummary,
    isDemo: boolean = true,
    caseTitle?: string,
    operatorName?: string
  ): void {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'pt',
      format: 'letter',
    });

    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
    const margin = 54;
    const contentWidth = pageWidth - margin * 2;
    let y = margin;

    // Header helper
    const drawPageDecorations = (pageNum: number, totalPages: number) => {
      doc.saveGraphicsState();
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8);
      doc.setTextColor(100, 116, 139);

      // Top running header
      doc.text(
        'DIGITAL FORENSIC INVESTIGATION REPORT | AUTOMATED ATTACK TIMELINE RECONSTRUCTION',
        margin,
        35
      );
      doc.setDrawColor(203, 213, 225);
      doc.setLineWidth(0.5);
      doc.line(margin, 40, pageWidth - margin, 40);

      // Bottom running footer
      doc.line(margin, pageHeight - 45, pageWidth - margin, pageHeight - 45);
      doc.text('CONFIDENTIAL & PROPRIETARY | FORENSIC INCIDENT DOCUMENTATION', margin, pageHeight - 32);
      const pageStr = `Page ${pageNum} of ${totalPages}`;
      doc.text(pageStr, pageWidth - margin - doc.getTextWidth(pageStr), pageHeight - 32);
      doc.restoreGraphicsState();
    };

    // Document Title
    y = 65;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.setTextColor(15, 23, 42);
    doc.text(caseTitle ? caseTitle.toUpperCase() : 'DIGITAL FORENSIC INVESTIGATION REPORT', margin, y);
    y += 18;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(71, 85, 105);
    doc.text('AI-Assisted Automated Attack Timeline Reconstruction & Digital Forensic Incident Reporting', margin, y);
    y += 12;

    doc.setDrawColor(15, 23, 42);
    doc.setLineWidth(1.5);
    doc.line(margin, y, pageWidth - margin, y);
    y += 14;

    // Provenance Banner
    if (isDemo) {
      doc.setFillColor(254, 243, 199);
      doc.setDrawColor(245, 158, 11);
      doc.rect(margin, y, contentWidth, 38, 'FD');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(146, 64, 14);
      doc.text('[!] DATA INTEGRITY NOTICE - DEMO DATASET (SIMULATED FORENSIC TELEMETRY)', margin + 10, y + 14);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7.5);
      doc.text(
        'This document was generated using a controlled simulation dataset for educational and evaluation purposes.',
        margin + 10,
        y + 26
      );
    } else {
      doc.setFillColor(220, 252, 231);
      doc.setDrawColor(16, 185, 129);
      doc.rect(margin, y, contentWidth, 38, 'FD');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(22, 101, 52);
      doc.text('[LIVE FORENSIC EVIDENCE RECORD] - SPLUNK ENTERPRISE LIVE TELEMETRY', margin + 10, y + 14);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7.5);
      doc.text(
        'This document contains normalized digital forensic evidence extracted directly from live Splunk Enterprise indexes.',
        margin + 10,
        y + 26
      );
    }
    y += 48;

    // Section 1: Incident Overview & Verdict
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(15, 23, 42);
    doc.text('1. Incident Overview & Threat Verdict', margin, y);
    y += 10;

    const metaTableBody = [
      [
        { content: 'Report Generated:', styles: { fontStyle: 'bold' as const } },
        summaryData.generated_at,
        { content: 'Operating Mode:', styles: { fontStyle: 'bold' as const } },
        isDemo ? 'DEMO / SIMULATED' : 'LIVE PRODUCTION',
      ],
      [
        { content: 'Analysis Engine:', styles: { fontStyle: 'bold' as const } },
        summaryData.methodology,
        { content: 'Incident Verdict:', styles: { fontStyle: 'bold' as const } },
        { content: summaryData.threat_verdict, styles: { fontStyle: 'bold' as const, textColor: [220, 38, 38] as [number, number, number] } },
      ],
      [
        { content: 'Time Scope:', styles: { fontStyle: 'bold' as const } },
        `${summaryData.time_scope.earliest_event} to ${summaryData.time_scope.latest_event}`,
        { content: 'Events Analyzed:', styles: { fontStyle: 'bold' as const } },
        String(summaryData.time_scope.total_events_analyzed),
      ],
    ];

    if (operatorName) {
      metaTableBody.push([
        { content: 'Lead Investigator:', styles: { fontStyle: 'bold' as const } },
        operatorName,
        { content: 'Custody Status:', styles: { fontStyle: 'bold' as const } },
        'Verified Forensic Evidence',
      ]);
    }

    autoTable(doc, {
      startY: y,
      margin: { left: margin, right: margin },
      body: metaTableBody,
      theme: 'grid',
      styles: { fontSize: 7.5, cellPadding: 3, textColor: [30, 41, 59] },
      headStyles: { fillColor: [248, 250, 252] },
    });

    y = (doc as any).lastAutoTable.finalY + 10;

    // Executive Summary Text
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(15, 23, 42);
    doc.text('Executive Summary:', margin, y);
    y += 11;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(30, 41, 59);
    const splitExec = doc.splitTextToSize(summaryData.executive_summary, contentWidth);
    doc.text(splitExec, margin, y);
    y += splitExec.length * 10 + 12;

    // Section 2: Scope & Entity Attribution
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(15, 23, 42);
    doc.text('2. Scope & Entity Attribution', margin, y);
    y += 10;

    const entities = summaryData.entities;
    autoTable(doc, {
      startY: y,
      margin: { left: margin, right: margin },
      body: [
        [{ content: 'Identified Threat Actor(s):', styles: { fontStyle: 'bold' as const, cellWidth: 140 } }, entities.actors.join(', ') || 'None identified'],
        [{ content: 'Targeted Accounts:', styles: { fontStyle: 'bold' as const, cellWidth: 140 } }, entities.targeted_accounts.join(', ') || 'None identified'],
        [{ content: 'Rogue / Created Accounts:', styles: { fontStyle: 'bold' as const, cellWidth: 140 } }, entities.created_accounts.join(', ') || 'None created'],
        [{ content: 'MITRE Kill Chain Phases:', styles: { fontStyle: 'bold' as const, cellWidth: 140 } }, entities.detected_phases.join(', ') || 'Routine baseline'],
      ],
      theme: 'grid',
      styles: { fontSize: 7.5, cellPadding: 3, textColor: [30, 41, 59] },
    });

    y = (doc as any).lastAutoTable.finalY + 16;

    // Section 3: Chronological Attack Timeline
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(15, 23, 42);
    doc.text('3. Chronological Forensic Attack Timeline', margin, y);
    y += 10;

    const timelineRows = timelineData.timeline.map((item) => {
      const narrative = `[Evidence]: ${item.confirmed_facts}\n[Hypothesis]: ${item.correlation_reason}`;
      const actorTarget = `Src: ${item.actor}\nTgt: ${item.target_user} @ ${item.target_host}`;
      return [
        String(item.step),
        item.timestamp,
        `${item.event_id}\n${item.event_name.slice(0, 22)}`,
        actorTarget,
        narrative,
        item.suspicion_level,
      ];
    });

    autoTable(doc, {
      startY: y,
      margin: { left: margin, right: margin },
      head: [['Step', 'Timestamp', 'Event ID', 'Actor -> Target', 'Confirmed Facts & Correlation Rationale', 'Suspicion']],
      body: timelineRows,
      theme: 'grid',
      styles: { fontSize: 7, cellPadding: 3, textColor: [15, 23, 42], overflow: 'linebreak' },
      headStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold', fontSize: 7.5 },
      columnStyles: {
        0: { cellWidth: 26 },
        1: { cellWidth: 70 },
        2: { cellWidth: 65 },
        3: { cellWidth: 90 },
        4: { cellWidth: 185 },
        5: { cellWidth: 65 },
      },
    });

    y = (doc as any).lastAutoTable.finalY + 16;

    // Check if new page needed
    if (y > pageHeight - 140) {
      doc.addPage();
      y = 60;
    }

    // Section 4: Identified Correlation Chains
    if (summaryData.correlation_chains && summaryData.correlation_chains.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(11);
      doc.setTextColor(15, 23, 42);
      doc.text('4. Identified Correlation Chains & Attack Patterns', margin, y);
      y += 10;

      const chainRows = summaryData.correlation_chains.map((c) => [
        c.chain_id,
        c.title,
        c.primary_actor,
        c.verdict,
        c.description,
      ]);

      autoTable(doc, {
        startY: y,
        margin: { left: margin, right: margin },
        head: [['Chain ID', 'Pattern Title', 'Primary Actor', 'Verdict', 'Forensic Description']],
        body: chainRows,
        theme: 'grid',
        styles: { fontSize: 7, cellPadding: 3, textColor: [15, 23, 42] },
        headStyles: { fillColor: [30, 41, 59], textColor: [255, 255, 255], fontStyle: 'bold' },
      });

      y = (doc as any).lastAutoTable.finalY + 16;
    }

    // Check if new page needed
    if (y > pageHeight - 160) {
      doc.addPage();
      y = 60;
    }

    // Section 5: Defensive Recommendations
    if (summaryData.recommendations && summaryData.recommendations.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(11);
      doc.setTextColor(15, 23, 42);
      doc.text('5. Defensive Recommendations & Remediation Guidance', margin, y);
      y += 10;

      const recRows = summaryData.recommendations.map((r) => [r.priority, r.action, r.details]);

      autoTable(doc, {
        startY: y,
        margin: { left: margin, right: margin },
        head: [['Priority', 'Action Item', 'Technical Remediation Details']],
        body: recRows,
        theme: 'grid',
        styles: { fontSize: 7, cellPadding: 3, textColor: [15, 23, 42] },
        headStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold' },
        columnStyles: {
          0: { cellWidth: 75 },
          1: { cellWidth: 125 },
          2: { cellWidth: contentWidth - 200 },
        },
      });

      y = (doc as any).lastAutoTable.finalY + 16;
    }

    // Check if new page needed
    if (y > pageHeight - 100) {
      doc.addPage();
      y = 60;
    }

    // Section 6: Limitations
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(15, 23, 42);
    doc.text('6. Forensic Scope & Investigation Limitations', margin, y);
    y += 10;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(71, 85, 105);
    const splitLimits = doc.splitTextToSize(summaryData.forensic_limitations, contentWidth);
    doc.text(splitLimits, margin, y);
    y += splitLimits.length * 9 + 8;

    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.5);
    doc.line(margin, y, pageWidth - margin, y);
    y += 10;

    doc.setFont('helvetica', 'italic');
    doc.setFontSize(7);
    doc.setTextColor(100, 116, 139);
    doc.text(
      'Report compiled by Automated Forensic Analysis Engine. Document authenticated for Digital Forensic Incident Reporting.',
      margin,
      y
    );

    // Apply two-pass headers and footers to all pages
    const totalPages = (doc.internal as any).getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      drawPageDecorations(i, totalPages);
    }

    // Trigger download
    const dateSlug = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
    doc.save(`Forensic_Incident_Report_${dateSlug}.pdf`);
  }
}
